#!/usr/bin/env python3
"""Independent exact cell and tensor calculation for the 02LO fresh check."""
from collections import defaultdict
from datetime import datetime, timezone
from itertools import product

RAYS = ((1,0),(0,1),(-1,1),(-1,0),(0,-1),(1,-1))

def quotient(a,b,c):
    """L generated by (a,0),(b,c); exact reduction and vertex coordinates."""
    vertices=list(product(range(a),range(c)))
    lookup={v:i for i,v in enumerate(vertices)}
    def reduce(x,y):
        q,r=divmod(y,c)
        return lookup[((x-q*b)%a,r)]
    assert len(vertices)==a*c
    for x,y in vertices:
        assert reduce(x+a,y)==reduce(x,y)==reduce(x+b,y+c)
    return vertices,reduce

def calculate(a,b,c):
    vertices,reduce=quotient(a,b,c)
    n=len(vertices)
    tensor=[[[0]*n for _ in range(n)] for _ in range(n)]
    for i,(x,y) in enumerate(vertices):
        differences=[]
        for dx,dy in RAYS:
            row=[0]*n
            row[reduce(x+dx,y+dy)]+=1
            row[i]-=1
            differences.append(row)
        for j in range(n):
            for k in range(n):
                tensor[i][j][k]=sum(
                    -differences[r][j]*differences[r][k]
                    +differences[r][j]*differences[(r+1)%6][k]
                    +differences[(r+1)%6][j]*differences[r][k]
                    for r in range(6))
    cubic_tensor=defaultdict(int)
    for i,j,k in product(range(n),repeat=3):
        value=tensor[i][j][k]
        assert value==tensor[j][i][k]==tensor[k][j][i]
        cubic_tensor[tuple(sorted((i,j,k)))]+=value
    for j,k in product(range(n),repeat=2):
        assert sum(tensor[i][j][k] for i in range(n))==0
        assert sum(tensor[j][i][k] for i in range(n))==0
        assert sum(tensor[j][k][i] for i in range(n))==0
    cubic_cells=defaultdict(int)
    edge_count=triangle_count=0
    for i,(x,y) in enumerate(vertices):
        cubic_cells[(i,i,i)]+=6
        for dx,dy in RAYS[:3]:
            j=reduce(x+dx,y+dy)
            cubic_cells[tuple(sorted((i,i,j)))]-=3
            cubic_cells[tuple(sorted((i,j,j)))]-=3
            edge_count+=1
        first=(i,reduce(x+1,y),reduce(x,y+1))
        second=(reduce(x+1,y+1),reduce(x+1,y),reduce(x,y+1))
        for triangle in (first,second):
            cubic_cells[tuple(sorted(triangle))]+=6
            triangle_count+=1
    assert edge_count==3*n and triangle_count==2*n
    clean=lambda d:{k:v for k,v in d.items() if v}
    assert clean(cubic_tensor)==clean(cubic_cells)
    return tensor

print('UTC:',datetime.now(timezone.utc).isoformat())
count=entries=0
for a in range(1,6):
    for c in range(1,6):
        if a*c>16:
            continue
        for b in range(a):
            tensor=calculate(a,b,c)
            count+=1
            entries+=(a*c)**3
print('Hermite-basis lattices:',count,'; complete tensor entries:',entries)
print('All symmetric; all three constant contractions vanish; cell cubics agree.')
for d in range(1,31):
    tensor=calculate(1,0,d)
    assert all(value==0 for plane in tensor for row in plane for value in row)
print('Cyclic quotient cases d=1,...,30: every tensor entry is zero.')
tensor=calculate(2,0,2)
for i,j,k in product(range(4),repeat=3):
    assert tensor[i][j][k]=={1:6,2:-2,3:2}[len({i,j,k})]
print('Four-vertex quotient: all 64 ordered entries have values6,-2,2 as claimed.')
boundary_matrix=[[-int(i==j)+int((i-j)%6 in (1,5)) for j in range(6)]
                 for i in range(6)]
k_squared=sum(map(sum,boundary_matrix))
euler=6
c2=euler-k_squared
p1=-2*c2
assert (k_squared,c2,p1)==(6,0,0)
print('Hexagon: K²=6, Euler=6, restricted c2=0, restricted p1=0.')
print('Finite arithmetic supplements the separately written all-lattice proof.')
